FILE rpcapd/daemon.c
1529: static int
1530: daemon_msg_open_req(uint8 ver, struct daemon_slpars *pars, uint32 plen,
1531:     char *source, size_t sourcelen)
1532: {
1533: 	char errbuf[PCAP_ERRBUF_SIZE];		                            
1534: 	char errmsgbuf[PCAP_ERRBUF_SIZE];	                                          
1535: 	pcap_t *fp;				                       
1536: 	int nread;
1537: 	char sendbuf[RPCAP_NETBUF_SIZE];	                                                        
1538: 	int sendbufidx = 0;			                                                           
1539: 	struct rpcap_openreply *openreply;	                     
1540: 
1541: 	if (plen > sourcelen - 1)
1542: 	{
1543: 		pcap_snprintf(errmsgbuf, PCAP_ERRBUF_SIZE, "Source string too long");
1544: 		goto error;
1545: 	}
1546: 
1547: 	nread = sock_recv(pars->sockctrl, source, plen,
1548: 	    SOCK_RECEIVEALL_YES|SOCK_EOF_IS_ERROR, errbuf, PCAP_ERRBUF_SIZE);
1549: 	if (nread == -1)
1550: 	{
1551: 		rpcapd_log(LOGPRIO_ERROR, "Read from client failed: %s", errbuf);
1552: 		return -1;
1553: 	}
1554: 	source[nread] = '\0';
1555: 	plen -= nread;
1556: 
1557: 	                                                             
1558: 	                       
1559: 
1560: 	                           
1561: 	                                                                                                          
1562: 	if ((fp = pcap_open_live(source,
1563: 			1500                   ,
1564: 			0                ,
1565: 			1000                   ,
1566: 			errmsgbuf)) == NULL)
1567: 		goto error;
1568: 
1569: 	                                             
1570: 	if (sock_bufferize(NULL, sizeof(struct rpcap_header), NULL, &sendbufidx,
1571: 	    RPCAP_NETBUF_SIZE, SOCKBUF_CHECKONLY, errmsgbuf, PCAP_ERRBUF_SIZE) == -1)
1572: 		goto error;
1573: 
1574: 	rpcap_createhdr((struct rpcap_header *) sendbuf, ver,
1575: 	    RPCAP_MSG_OPEN_REPLY, 0, sizeof(struct rpcap_openreply));
1576: 
1577: 	openreply = (struct rpcap_openreply *) &sendbuf[sendbufidx];
1578: 
1579: 	if (sock_bufferize(NULL, sizeof(struct rpcap_openreply), NULL, &sendbufidx,
1580: 	    RPCAP_NETBUF_SIZE, SOCKBUF_CHECKONLY, errmsgbuf, PCAP_ERRBUF_SIZE) == -1)
1581: 		goto error;
1582: 
1583: 	memset(openreply, 0, sizeof(struct rpcap_openreply));
1584: 	openreply->linktype = htonl(pcap_datalink(fp));
1585: 	openreply->tzoff = 0;                                         
1586: 
1587: 	                              
1588: 	pcap_close(fp);
1589: 
1590: 	                  
1591: 	if (sock_send(pars->sockctrl, sendbuf, sendbufidx, errbuf, PCAP_ERRBUF_SIZE) == -1)
1592: 	{
1593: 		rpcapd_log(LOGPRIO_ERROR, "Send to client failed: %s", errbuf);
1594: 		return -1;
1595: 	}
1596: 	return 0;
1597: 
1598: error:
1599: 	if (rpcap_senderror(pars->sockctrl, ver, PCAP_ERR_OPEN,
1600: 	    errmsgbuf, errbuf) == -1)
1601: 	{
1602: 		                                          
1603: 		rpcapd_log(LOGPRIO_ERROR, "Send to client failed: %s", errbuf);
1604: 		return -1;
1605: 	}
1606: 
1607: 	                                                                          
1608: 	if (rpcapd_discard(pars->sockctrl, plen) == -1)
1609: 	{
1610: 		return -1;
1611: 	}
1612: 	return 0;
1613: }

